INSERT INTO sys_menu(menu_name,parent_id,order_num,path,component,route_name,is_frame,is_cache,menu_type,visible,status,perms,icon,create_by,create_time,update_by,update_time,remark) SELECT '期货仓单',@p,11,'warehouse','future/research','FutureWarehouse',1,0,'C','0','0','future:history:list','tickets','admin',NOW(),'admin',NOW(),'t_future_warehouse_receipt_daily' WHERE NOT EXISTS(SELECT 1 FROM sys_menu WHERE parent_id=@p AND path='warehouse');
INSERT INTO sys_menu(menu_name,parent_id,order_num,path,component,route_name,is_frame,is_cache,menu_type,visible,status,perms,icon,create_by,create_time,update_by,update_time,remark) SELECT '期货持仓',@p,12,'positions','future/research','FuturePositions',1,0,'C','0','0','future:history:list','user','admin',NOW(),'admin',NOW(),'t_future_contract_position_daily' WHERE NOT EXISTS(SELECT 1 FROM sys_menu WHERE parent_id=@p AND path='positions');
INSERT INTO sys_role_menu(role_id,menu_id) SELECT 1,menu_id FROM sys_menu WHERE parent_id=@p AND path IN('warehouse','positions') AND NOT EXISTS(SELECT 1 FROM sys_role_menu x WHERE x.role_id=1 AND x.menu_id=sys_menu.menu_id);
